import type { ReactNode } from "react";
import { AbsoluteFill, Html5Audio, interpolate, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";
import { Backdrop, Bob, Chip, TekoMark, Wordmark } from "../components/ui";
import { C, display, FPS, pop, ramp, sans, sec } from "../theme";

/*
 * 30-second ad. The hook keeps the skit's own voice; the rest is voice-over, sound effects and
 * background music from public/audio (generated by scripts/make-ad-audio.py), over the real app recording.
 */

const HOOK = { at: 0, len: 3.4, src: "footage/phase1.mp4", from: 16.3 };
const PROBLEM = { at: 3.4, len: 2.8 };
const BRAND = { at: 6.2, len: 2.6 };
const BEATS = [
  { n: "01", title: "Join with your face.", sub: "One link. No forms, no passwords.", src: 81.0 },
  { n: "02", title: "Chip in once.", sub: "Everyone fills the same pot, in dollars.", src: 92.0 },
  { n: "03", title: "Spend together.", sub: "Pay from the pot. Everyone sees it instantly.", src: 109.0 },
  { n: "04", title: "It settles itself.", sub: "On the last day, everyone gets their share back.", src: 140.0 },
];
const BEAT_AT = 8.8;
const BEAT_LEN = 4.1;
export const AD_SECONDS = 30;
const END = { at: BEAT_AT + BEATS.length * BEAT_LEN, len: AD_SECONDS - (BEAT_AT + BEATS.length * BEAT_LEN) };

export const Ad: React.FC = () => (
  <AbsoluteFill style={{ background: C.bg }}>
    <Sequence from={sec(HOOK.at)} durationInFrames={sec(HOOK.len)}>
      <Hook />
    </Sequence>
    <Sequence from={sec(PROBLEM.at)} durationInFrames={sec(PROBLEM.len)}>
      <Problem />
    </Sequence>
    <Sequence from={sec(BRAND.at)} durationInFrames={sec(BRAND.len)}>
      <Brand />
    </Sequence>
    {BEATS.map((b, i) => (
      <Sequence key={b.n} from={sec(BEAT_AT + i * BEAT_LEN)} durationInFrames={sec(BEAT_LEN)}>
        <Beat {...b} i={i} />
      </Sequence>
    ))}
    <Sequence from={sec(END.at)} durationInFrames={sec(END.len)}>
      <EndCard />
    </Sequence>
    <Soundtrack />
  </AbsoluteFill>
);

const MUSIC_VOLUME = 0.25;

/** [seconds, file, volume] */
const CUES: [number, string, number][] = [
  // voice-over
  [3.35, "vo1", 1],
  [6.45, "vo2", 1],
  [BEAT_AT + 0.25, "vo3", 1],
  [BEAT_AT + BEAT_LEN + 0.25, "vo4", 1],
  [BEAT_AT + 2 * BEAT_LEN + 0.25, "vo5", 1],
  [BEAT_AT + 3 * BEAT_LEN + 0.25, "vo6", 1],
  [END.at + 0.45, "vo7", 1],
  // transitions
  ...[PROBLEM.at, BRAND.at, ...BEATS.map((_, i) => BEAT_AT + i * BEAT_LEN), END.at].map((at): [number, string, number] => [at - 0.2, "whoosh", 0.35]),
  // text pops
  [0.2, "pop", 0.4],
  [PROBLEM.at + 0.05, "pop", 0.35],
  [PROBLEM.at + 0.6, "pop", 0.35],
  [PROBLEM.at + 1.2, "pop", 0.4],
  ...BEATS.map((_, i): [number, string, number] => [BEAT_AT + i * BEAT_LEN + 0.15, "pop", 0.3]),
  // brand + payoff
  [BRAND.at + 0.05, "chime", 0.45],
  [BEAT_AT + 3 * BEAT_LEN + 1.2, "coin", 0.4],
  [END.at + 0.1, "chime", 0.45],
];

const Soundtrack: React.FC = () => (
  <>
    {/* Music sits under the skit's own voice in the hook, then plays at 25%. */}
    <Html5Audio src={staticFile("audio/music.wav")} volume={(f) => (f < sec(HOOK.len) ? MUSIC_VOLUME * 0.5 : MUSIC_VOLUME)} />
    {CUES.map(([at, file, volume], i) => (
      <Sequence key={`${file}-${i}`} from={Math.max(0, sec(at))} layout="none">
        <Html5Audio src={staticFile(`audio/${file}.wav`)} volume={volume} />
      </Sequence>
    ))}
  </>
);

/** Scene-level fade and slow zoom so cuts feel snappy but not hard. */
const Shell: React.FC<{ len: number; children: ReactNode }> = ({ len, children }) => {
  const t = useCurrentFrame() / FPS;
  const o = ramp(t, 0, 0.18) * (1 - ramp(t, len - 0.18, len));
  const z = interpolate(t, [0, len], [1.03, 1]);
  return <AbsoluteFill style={{ opacity: o, transform: `scale(${z})` }}>{children}</AbsoluteFill>;
};

/** 0–3.4s — the skit's punchline as the hook. */
const Hook: React.FC = () => {
  const f = useCurrentFrame();
  const p = pop(f, 0.2);
  return (
    <Shell len={HOOK.len}>
      <OffthreadVideo src={staticFile(HOOK.src)} trimBefore={sec(HOOK.from)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0) 50%, rgba(0,0,0,0.55))" }} />
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          bottom: 90,
          textAlign: "center",
          fontFamily: display,
          fontWeight: 800,
          fontSize: 96,
          letterSpacing: "-0.03em",
          color: "#fff",
          opacity: p,
          transform: `scale(${0.85 + p * 0.15})`,
          textShadow: "0 6px 30px rgba(0,0,0,0.4)",
        }}
      >
        “Then who do I pay?”
      </div>
    </Shell>
  );
};

/** 3.4–6.2s — the mess, line by line. */
const Problem: React.FC = () => {
  const f = useCurrentFrame();
  const words = [
    { text: "Three countries.", at: 0.05, color: C.ink },
    { text: "Three currencies.", at: 0.6, color: C.ink },
    { text: "One messy group chat.", at: 1.2, color: C.orange },
  ];
  return (
    <Shell len={PROBLEM.len}>
      <Backdrop />
      <AbsoluteFill style={{ justifyContent: "center", paddingLeft: 150 }}>
        {words.map((w, i) => {
          const p = pop(f, w.at, { damping: 12 });
          const shake = i === 2 ? Math.sin(f / 2) * 0.6 * p : 0;
          return (
            <div
              key={w.text}
              style={{
                fontFamily: display,
                fontWeight: 800,
                fontSize: 130,
                lineHeight: 1.05,
                letterSpacing: "-0.035em",
                color: w.color,
                opacity: p,
                transform: `translateX(${(1 - p) * -80}px) rotate(${(1 - p) * -3 + shake}deg)`,
              }}
            >
              {w.text}
            </div>
          );
        })}
      </AbsoluteFill>
    </Shell>
  );
};

/** 6.2–8.8s — brand reveal on teal. */
const Brand: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const mark = pop(f, 0.05, { damping: 10 });
  const word = pop(f, 0.35);
  const line = ramp(t, 0.8, 1.2);
  const wipe = ramp(t, 0, 0.35);
  return (
    <Shell len={BRAND.len}>
      <AbsoluteFill style={{ background: C.primary, clipPath: `circle(${wipe * 120}% at 50% 50%)`, alignItems: "center", justifyContent: "center" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 30 }}>
          <div style={{ transform: `scale(${mark}) rotate(${(1 - mark) * -40}deg)` }}>
            <Bob amp={6} sway={3}>
              <TekoMark size={220} />
            </Bob>
          </div>
          <div style={{ opacity: word, transform: `translateX(${(1 - word) * 60}px)` }}>
            <Wordmark size={190} color="#fff" />
          </div>
        </div>
        <div style={{ marginTop: 30, opacity: line, transform: `translateY(${(1 - line) * 20}px)`, fontFamily: sans, fontWeight: 700, fontSize: 56, color: "#fff" }}>
          One pot for the whole trip.
        </div>
      </AbsoluteFill>
    </Shell>
  );
};

/** 8.8–25.2s — four quick beats on the real app. */
const Beat: React.FC<(typeof BEATS)[number] & { i: number }> = ({ n, title, sub, src, i }) => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const num = pop(f, 0.05);
  const head = pop(f, 0.15, { damping: 12 });
  const s = ramp(t, 0.5, 0.9);
  const stage = pop(f, 0.1, { damping: 15 });
  const scale = 0.84;
  return (
    <Shell len={BEAT_LEN}>
      <Backdrop />
      <div style={{ position: "absolute", left: 150, top: 120, display: "flex", gap: 12 }}>
        {BEATS.map((b, j) => (
          <div key={b.n} style={{ width: j === i ? 64 : 16, height: 16, borderRadius: 16, background: j <= i ? C.primary : C.line }} />
        ))}
      </div>
      <div style={{ position: "absolute", left: 150, top: 300, width: 880 }}>
        <div style={{ fontFamily: display, fontWeight: 800, fontSize: 44, color: C.orange, opacity: num, transform: `translateY(${(1 - num) * 20}px)` }}>{n}</div>
        <div
          style={{
            fontFamily: display,
            fontWeight: 800,
            fontSize: 124,
            lineHeight: 1.0,
            letterSpacing: "-0.035em",
            color: C.ink,
            marginTop: 8,
            opacity: head,
            transform: `translateX(${(1 - head) * -70}px)`,
          }}
        >
          {title}
        </div>
        <div style={{ marginTop: 28, fontFamily: sans, fontWeight: 600, fontSize: 46, lineHeight: 1.25, color: C.inkSoft, opacity: s }}>{sub}</div>
      </div>
      <div
        style={{
          position: "absolute",
          left: 1080,
          top: 110,
          width: 880 * scale,
          height: 885 * scale,
          borderRadius: 44,
          overflow: "hidden",
          background: "#FAF8F3",
          boxShadow: C.shadow,
          border: `1px solid ${C.line}`,
          opacity: stage,
          transform: `translateY(${(1 - stage) * 140 + Math.sin(f / 25) * 6}px) rotate(${(1 - stage) * 4 + (i % 2 ? -1.5 : 1.5)}deg)`,
        }}
      >
        <OffthreadVideo
          src={staticFile("footage/appdemo.mp4")}
          trimBefore={sec(src)}
          muted
          style={{ position: "absolute", width: 1920 * scale, height: 1080 * scale, left: -900 * scale, top: -40 * scale }}
        />
      </div>
    </Shell>
  );
};

/** 25.2–30s — tagline with the recorded voice line. */
const EndCard: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const mark = pop(f, 0.1, { damping: 10 });
  const line = pop(f, 0.4);
  const chips = ramp(t, 1.0, 1.4);
  const url = ramp(t, 1.4, 1.8);
  return (
    <AbsoluteFill style={{ opacity: ramp(t, 0, 0.2) }}>
      <Backdrop />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div style={{ transform: `scale(${mark})` }}>
          <Bob amp={10} sway={3}>
            <TekoMark size={250} />
          </Bob>
        </div>
        <div
          style={{
            marginTop: 10,
            opacity: line,
            transform: `translateY(${(1 - line) * 40}px)`,
            fontFamily: display,
            fontWeight: 800,
            fontSize: 110,
            letterSpacing: "-0.035em",
            color: C.ink,
          }}
        >
          Stressless trips with <span style={{ color: C.primary }}>tekosue</span>
          <span style={{ color: C.orange }}>.</span>
        </div>
        <div style={{ marginTop: 30, display: "flex", gap: 16, opacity: chips, transform: `translateY(${(1 - chips) * 16}px)` }}>
          <Chip tone="primary">Face ID only</Chip>
          <Chip tone="green">Settles itself</Chip>
          <Chip tone="monad">◆ Live on Monad testnet</Chip>
        </div>
        <div style={{ marginTop: 34, opacity: url, fontFamily: sans, fontWeight: 700, fontSize: 44, color: C.primary }}>www.tekosue.xyz</div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
